// Rows with a website and an empty email cell that were not looked up yet.
// A row whose status starts with "retry" (timeout, blocked...) is tried again; every other status is final.
const s = $('Sheet settings').first().json;
const rows = [];
for (const { json: r } of $input.all()) {
  const website = String(r[s.websiteColumn] ?? '').trim();
  const email = String(r[s.emailColumn] ?? '').trim();
  const status = String(r[s.statusColumn] ?? '').trim().toLowerCase();
  if (!website || email) continue;
  if (status && !status.startsWith('retry')) continue;
  rows.push({ row_number: r.row_number, website, email: '', phone: String(r[s.phoneColumn] ?? '') });
  if (rows.length >= s.maxRowsPerRun) break;
}
if (!rows.length) return [];
return [{ json: { rows } }];

// One update per sheet row, matched by row_number (= rowId). Only empty cells are filled:
// the Actor's `fill` already leaves out columns that had a value, and the sheet is checked again here.
const s = $('Sheet settings').first().json;
const sheet = new Map($('Read the sheet').all().map(({ json: r }) => [String(r.row_number), r]));
const empty = (v) => String(v ?? '').trim() === '';
const statusOf = (r) => {
  if (r.emailStatus === 'new_email') return r.fromPreviousRun ? 'email found (earlier run)' : 'email found';
  if (r.emailStatus === 'no_email_found') return 'no email on the website';
  if (r.emailStatus === 'already_had_email') return 'had an email';
  if (r.retryable) return `retry: ${r.errorType}`;
  if (r.errorType === 'not_a_website') return 'social or directory page, not a website';
  return `not read: ${r.errorType ?? 'unknown'}`;
};
const checkedAt = $now.toISO();
const out = [];
const done = new Set();
for (const { json: r } of $input.all()) {
  const id = String(r.rowId ?? '');
  if (!id || done.has(id) || !sheet.has(id)) continue;
  done.add(id);
  const row = sheet.get(id);
  const update = { row_number: row.row_number, [s.statusColumn]: statusOf(r), 'Email checked at': checkedAt };
  const fill = r.fill || {};
  if (fill.email && empty(row[s.emailColumn])) update[s.emailColumn] = fill.email;
  if (fill.phone && s.phoneColumn in row && empty(row[s.phoneColumn])) update[s.phoneColumn] = fill.phone;
  if (r.emailsText && 'All emails' in row && empty(row['All emails'])) update['All emails'] = r.emailsText;
  out.push({ json: update });
}
return out;
